// Regenerates src/snapshot.gen.ts from the vendored src/snapshot.js.
// The server bundle cannot read data files at runtime, so the browser-side
// snapshot ships as a string constant. test/snapshot.test.ts fails when the
// two drift apart.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const source = readFileSync(`${root}src/snapshot.js`, "utf8");
const output = [
  "// Generated by scripts/gen-snapshot.mjs from src/snapshot.js. Do not edit.",
  "// snapshot.js is vendored from browser-use/jev-ultrafast (MIT).",
  `export const READ_STATE: string = ${JSON.stringify(source.trim())};`,
  "",
].join("\n");
writeFileSync(`${root}src/snapshot.gen.ts`, output);
